// Web rendering of native main 34557847. Fictional data, never a connected account.
const glyph = name => `<svg aria-hidden="true"><use href="/assets/parent-icons.svg#${name}"></use></svg>`;
const row = (name, value) => `<div class="ios-row"><span>${name}</span><span>${value}<i>⌄</i></span></div>`;
const group = (title, body, target = '') => `<div class="ios-group" ${target ? `data-parent-target="${target}"` : ''}><p class="ios-section-label">${title}</p><div class="ios-inset">${body}</div></div>`;
const profile = `<div class="ios-profile" data-parent-target="today">${row('Child','Explorer')}${row('Date range','Today')}<p class="ios-caption">Updated Oct 13, 9:41 AM · iPhone time</p></div>`;
const metrics = `<div class="ios-metrics"><div><strong>2</strong><span>Questions</span></div><div><strong>1</strong><span>Math missions</span></div><div><strong>1</strong><span>Stories</span></div></div><p class="ios-caption">Saved activities · Today</p>`;
const moment = `<div class="ios-moment" data-parent-target="together"><strong>${glyph('heart')} A moment together</strong><p>Ask Explorer what they noticed while exploring their latest question.</p><b>Why this suggestion?</b></div>`;
const activity = `<div class="ios-activity"><div><b>Curiosity</b><span>Oct 13, 9:35 AM</span></div><strong>Why does the Moon change shape?</strong><p>We see different parts of the Moon lit by the Sun.</p></div>`;
const discoveryNote = `<p class="ios-caption ios-discovery-note">Discovery cards are bundled explanations checked against sources by an AI assistant, not live AI answers or specialist-reviewed lessons. It includes prerecorded Cedar narration for offline listening. Human listening and specialist review are not claimed. It uses the latest safeguards received by the Watch; custom guidance keeps cards unavailable. Listening is not added to activity reports.</p>`;

export const parentChapters = [
  {id:'today', label:'Today', tab:0, title:'A clear view.\nOf their day.', summary:'Choose a child. Choose a time window. See the activities that have been saved.', why:'The child selector stays close to the information it controls. Date ranges and the last successful update make the numbers interpretable: whose activity, over which period, and how fresh it is. The native app also clears the old child’s state when switching profiles, so a delayed response cannot quietly show the wrong child’s information.', limit:'These are activity counts, not scores or proof of learning. Offline discovery listening is not included. An update time is not a claim of continuous monitoring.'},
  {id:'together', label:'Together', tab:0, title:'A small moment.\nBack to you.', summary:'A recent discovery becomes an invitation to talk, notice, or try something together.', why:'“A moment together” is grounded in a saved activity. Its “Why this suggestion?” view makes that connection explicit. Inviting a child to explain an idea in their own words can help a parent hear what made sense and where a little support would be useful. The design brings the experience back into a human relationship.', limit:'A conversation starter is not an assessment of ability, a diagnosis, or an inference about your child’s personality.'},
  {id:'activity', label:'Activity', tab:1, title:'See the exchange.\nKeep the context.', summary:'Review saved questions and answers. See when a safeguard shaped a response. Delete an individual activity.', why:'A summary can be useful; the underlying exchange gives it meaning. Activity filters help a parent find Ask, Math, Stories, or safeguard interventions. Details can include the original question, answer, supported versus independent Math practice, and a recorded policy reason. Deletion asks for confirmation and should only leave the detail screen after it succeeds.', limit:'Reports cover saved events, not every offline experience. A safeguard notice describes an intervention; it is not an emergency alert or a promise that everything was detected.'},
  {id:'topics', label:'Topics', tab:2, title:'Your family.\nYour guidance.', summary:'Choose an age-appropriate explanation, a grown-up conversation, or no discussion for supported topics.', why:'Readiness and family values are contextual. The current iOS source has preferences for religion, violence, non-explicit body development, drugs and alcohol, clean profanity explanations, politics and civics, and money and product literacy. Each choice is named by its consequence. Essential protections remain separate, so a preference cannot authorize harmful instructions, exploitation, or commercial persuasion.', limit:'Expanded controls depend on service support and still require release validation. Questions about being hurt or feeling unsafe must retain supportive guidance toward a trusted adult.'},
  {id:'reading', label:'Reading', tab:2, title:'Set a pace.\nLet the story breathe.', summary:'Hear a reading-speed sample before sending your choice to the paired Watch.', why:'The parent can listen before deciding. Calm is the starting speed. The native app distinguishes “Saved here. Waiting for the paired Watch.” from “Applied on the paired Watch.” That difference matters: a tap on the phone is not proof that a device has received a setting. Downloaded books remain available offline; they do not require daily reapproval.', limit:'This website tour does not send settings to a device. Its separate interactive audio preview uses prepared recordings.'},
  {id:'guidance', label:'Guidance', tab:2, title:'A useful foothold.\nRoom to grow.', summary:'Set the starting math level and choose a supported explanation style.', why:'A starting level is a place to begin, not a permanent label. The current source includes age and starting Math controls, with difficulty adapting as practice continues. Bounded guidance choices—shorter sentences, familiar everyday examples, or avoiding scary imagery—make the requested support understandable. Existing progress is preserved rather than reset to a new-profile default.', limit:'TrustinJr initially focuses on ages 4–5. Wider age choices in development source are not an announcement of broader release support. Illustrated books keep their fixed wording; no learning gains are promised.'},
  {id:'setup', label:'Watch setup', tab:3, title:'Connected.\nOn your terms.', summary:'Choose a child, prepare the connection, and send it to the paired Watch.', why:'Setup separates a parent account, a child profile, and a Watch’s access. The device list states access expiry instead of pretending the Watch is currently online. Disconnect asks for confirmation and explains its scope: it stops future server access, without unpairing Apple devices or deleting the parent account. Watch-face customization remains an optional destination.', limit:'The current beta requires a Watch normally paired with this iPhone. Apple Family Setup is not supported in this beta. Master Guardian sharing is a separate, unfinished account-design direction and is not presented as available here.'}
];

export function parentScreen(id = 'overview') {
  let title = 'Trustin Jr.', body = '', tab = 0;
  if (id === 'overview' || id === 'today' || id === 'together') {
    body = `<div class="ios-title"><h3>Today</h3><img src="/assets/trustin.png" width="300" height="353" alt=""></div>${profile}${metrics}${moment}${discoveryNote}<div class="ios-row ios-recent"><strong>Recent activity</strong><span>View all</span></div>${activity}`;
  } else if (id === 'activity') {
    title = 'Activity'; tab = 1;
    body = `<p class="ios-back">‹ Activity report</p><div data-parent-target="activity"><h3 class="ios-detail-title">Why does the Moon change shape?</h3><p class="ios-caption">October 13 at 9:35 AM</p><h4>Question</h4><p>Why does the Moon change shape?</p><h4>Trustin’s answer</h4><p>The Moon stays round like a ball. As it travels around Earth, we see different parts of its sunlit side.</p><p class="ios-caption">Activity time: 1 min</p><p class="ios-delete">Delete this activity</p></div>`;
  } else if (id === 'topics') {
    title = 'Safeguards'; tab = 2;
    body = `${group('Child',row('Child','Explorer'))}${group('Topic preferences',row('Religion','Ask a grown-up')+row('Violence','Block discussion')+row('Body development (non-explicit)','Ask a grown-up')+row('Drugs and alcohol','Ask a grown-up')+row('Profanity (clean explanations)','Age-appropriate explanation')+row('Politics and civics','Ask a grown-up')+row('Money and product literacy','Age-appropriate explanation'),'topics')}${group('Always protected',`<p>${glyph('shield')} Explicit sexual content, harmful instructions, exploitation, hate, privacy solicitation and commercial persuasion are blocked.</p><p class="ios-caption">Questions about being hurt or feeling unsafe still receive supportive guidance and encouragement to tell a trusted adult.</p>`)}<p class="ios-native-action">Save safeguards</p>`;
  } else if (id === 'reading') {
    title = 'Safeguards'; tab = 2;
    body = `${group('Child',row('Child','Explorer'))}${group('Story reading',`<p>Reading speed</p><div class="ios-speed"><span>Slower</span><b>Calm</b><span>Natural</span></div><div class="ios-row ios-native-action"><span>Hear sample</span><span>Send to Watch</span></div><p class="ios-caption">Calm is the starting speed. Downloaded books work offline.</p>`,'reading')}${group('Learning pace',row('Age','4–5')+row('Starting math level','Kindergarten')+'<p class="ios-caption">Difficulty adapts as your child practices.</p><p class="ios-caption">The two illustrated books use fixed, child-friendly wording.</p>')}`;
  } else if (id === 'guidance') {
    title = 'Safeguards'; tab = 2;
    body = `${group('Learning pace',row('Age','4–5')+row('Starting math level','Kindergarten')+'<p class="ios-caption">Difficulty adapts as your child practices.</p><p class="ios-caption">The two illustrated books use fixed, child-friendly wording.</p>')}${group('Your guidance',row('Explanation style','Use familiar everyday examples.'),'guidance')}<p class="ios-native-action">Save safeguards</p>${group('Always protected',`<p>${glyph('shield')} Essential protections remain in place.</p>`)}`;
  } else if (id === 'setup') {
    title = 'Watch setup'; tab = 3;
    body = `${group('1 · Choose a child',row('Child','Explorer')+'<p class="ios-native-action">Prepare connection</p>')}${group('2 · Connect Watch','<p>On the Watch, open Trustin Jr. → gear. Keep both apps open.</p><p class="ios-native-action">Send to Watch</p>','setup')}${group('Watches','<p>No Watch connected yet.</p><p class="ios-native-action">Refresh</p>')}${group('',`<div class="ios-row"><span>${glyph('watch')} Customize watch face</span><span>›</span></div>`)}<p class="ios-caption">Requires a Watch paired to this iPhone. Apple Family Setup isn’t supported in this beta.</p>`;
  }
  const tabs = [['sun','Today'],['clock','Activity'],['shield','Safeguards'],['watch','Watch setup']];
  // Purely illustrative screen. Website navigation is kept outside the device.
  return `<div class="ios-status"><span>9:41</span><span class="ios-island"></span><span>▰</span></div><div class="ios-nav-title">${title}</div><div class="ios-scroll">${body}</div><div class="ios-tabs">${tabs.map(([icon,label],index)=>`<div ${tab===index?'class="ios-selected"':''}>${glyph(icon)}<span>${label}</span></div>`).join('')}</div><div class="ios-home-bar"></div>`;
}
